import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"20、【觀】 坤下巽上","description":"周易尚氏學 - 20、【觀】 坤下巽上","frontmatter":{"title":"20、【觀】 坤下巽上","description":"周易尚氏學 - 20、【觀】 坤下巽上"},"headers":[],"relativePath":"classics/shangshi/025.md","filePath":"classics/shangshi/025.md"}'),s={name:"classics/shangshi/025.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_20、【觀】-坤下巽上" tabindex="-1">20、【觀】 坤下巽上 <a class="header-anchor" href="#_20、【觀】-坤下巽上" aria-label="Permalink to “20、【觀】 坤下巽上”">​</a></h1><p>五得尊位。下臨萬民。民為廟堂。萬民瞻仰。故曰觀。易林以艮為觀為視。象失傳。詳焦氏易治蓋即本此也。國之大事。在把與戎。禮之可觀。莫盛乎宗廟。宗廟之可觀。莫盛乎祭祀。初漱降神也。馬融雲。進爵灌地以降神也。卦巽為白茅。茅在地上。坤水沃之。縮酒之象也。灌地降神。其誠敬之心。孚於神明。禺（右頁）敬也。及至薦牲則扎簡略。一孔子曰帝（左衣）自既灌而往者。吾不欲觀之矣。與此義同也。</p><p>彖曰。大觀在上。順而巽。中正以觀天下。觀。漱而不薦。有孚禺（右頁）若。下觀而化也。觀天之神道。而四時不忒。聖人以神道設教。而天下服矣。</p><p>坤為天下。天下化則服矣。此聖人所以以神道設教也。觀亦候卦。故曰四時。臨曰元亨利貞。亦四時也。</p><p>象曰。風行地上。觀。先王以省方觀民設教。</p><p>坤為方為民。艮為觀。故曰省方。曰觀民。巽為命。故曰教。先王巡狩四方。觀風問俗。宣佈教化。亦若風行地上也。</p><p>初六。童觀，小人無咎。君子吝。</p><p>釋文。馬雲童猶獨也。鄭雲樨（左禾）也。而虞翻以艮為童。詁與鄭同。按馬說是也。太玄玄衝雲。童寡有也。而易林每以坤為寡。初坤體。上無應。陰遇陰失類。孤寡極矣。故曰童觀。其在小人。獨行踽蹈（左同）。尚可無咎。若君子則狹隘為病矣。故吝。蓋童之象不在艮。而在坤。初何以孤寡。則以上無應而行失類也。</p><h3 id="象曰。初六童觀。小人道也。" tabindex="-1">象曰。初六童觀。小人道也。 <a class="header-anchor" href="#象曰。初六童觀。小人道也。" aria-label="Permalink to “象曰。初六童觀。小人道也。”">​</a></h3><p>道行也。</p><p>六二。窺觀。利女貞。</p><p>說文窺閃也。傾頭門中視也。二應五。坤為門。二在門中。上窺九五。而坤為閉為羞。故羞縮不敢正視而窺觀也。聖人取象之精。非注視卦象。不知其微妙如此也。窺觀乃妾婦之行。故利女佔。若在丈夫。則可醜矣。</p><h3 id="象曰。窺觀女貞。亦可醜也。" tabindex="-1">象曰。窺觀女貞。亦可醜也。 <a class="header-anchor" href="#象曰。窺觀女貞。亦可醜也。" aria-label="Permalink to “象曰。窺觀女貞。亦可醜也。”">​</a></h3><p>醜謂不莊</p><p>六三。觀我生。進退。</p><p>凡我生皆謂應與。詩小雅。雖有兄弟。不如友生。易以陰陽相遇為朋友。故謂應與為我生。三應在上。故曰觀我生。進退。上巽為進退。進退者上下也。三與上相上下。謂三宜進居上。上宜退居三。各當位也。故象曰不失道。</p><h3 id="象曰。觀我生進退。未失道也。" tabindex="-1">象曰。觀我生進退。未失道也。 <a class="header-anchor" href="#象曰。觀我生進退。未失道也。" aria-label="Permalink to “象曰。觀我生進退。未失道也。”">​</a></h3><p>道行也。</p><p>六四。觀國之光。利用賓於王。</p><p>艮為國為光。四獨近五。故曰觀國之光。曰賓於王。王謂五。巽為利。言利於朝覲天子作賓王家也。巽為旅客。故曰賓。</p><h3 id="象曰。觀國之光。尚賓也。" tabindex="-1">象曰。觀國之光。尚賓也。 <a class="header-anchor" href="#象曰。觀國之光。尚賓也。" aria-label="Permalink to “象曰。觀國之光。尚賓也。”">​</a></h3><p>尚賓者。言賓於上也。</p><p>九五。觀我生。君子無咎。</p><p>此我生謂二。五應在二。二坤為民。故象曰觀民。九五為觀之主。亦艮之主。艮為君子。下觀萬民。撫部（左血）教養。故無咎也。</p><h3 id="象曰。觀我生。觀民也。" tabindex="-1">象曰。觀我生。觀民也。 <a class="header-anchor" href="#象曰。觀我生。觀民也。" aria-label="Permalink to “象曰。觀我生。觀民也。”">​</a></h3><p>觀民即指二。二坤為民。</p><p>上九。觀其生。君子無咎。</p><p>諸家或釋生為出為性為道。一人前後。詁即不同。似非。按其。謂五。生指三。上應在三。三坤體。坤民下附。皆五之民也。上貴而無位。高而無民。宜高尚其事矣。乃猶不忘情。欲應三而觀其生焉。故象曰志未平。</p><h3 id="象曰。觀其生。志未平也。" tabindex="-1">象曰。觀其生。志未平也。 <a class="header-anchor" href="#象曰。觀其生。志未平也。" aria-label="Permalink to “象曰。觀其生。志未平也。”">​</a></h3><p>巽為志。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
